import { randomUUID } from 'node:crypto';
import cors from 'cors';
import express from 'express';
import rateLimit from 'express-rate-limit';
import helmet from 'helmet';
import { pinoHttp } from 'pino-http';
import swaggerUi from 'swagger-ui-express';
import { env } from './config/env.js';
import { logger } from './config/logger.js';
import { openApiDocument } from './config/openapi.js';
import { errorHandler, notFound } from './middleware/error-handler.js';
import { authRoutes } from './routes/auth.routes.js';
import { dashboardRoutes } from './routes/dashboard.routes.js';
export const createApp = () => {
    const app = express();
    app.disable('x-powered-by');
    app.use((req, res, next) => { const id = req.get('x-request-id') ?? randomUUID(); res.setHeader('x-request-id', id); next(); });
    app.use(pinoHttp({ logger }));
    app.use(helmet());
    app.use(cors({ origin: env.FRONTEND_URL, credentials: true }));
    app.use(express.json({ limit: '1mb' }));
    app.use('/api/v1/auth/login', rateLimit({ windowMs: 15 * 60_000, limit: 10, standardHeaders: 'draft-8', legacyHeaders: false }));
    app.get('/health', (_req, res) => res.json({ data: { status: 'ok' } }));
    app.use('/api/v1/auth', authRoutes);
    app.use('/api/v1/dashboard', dashboardRoutes);
    app.use('/api/docs', swaggerUi.serve, swaggerUi.setup(openApiDocument));
    app.get('/api/docs.json', (_req, res) => res.json(openApiDocument));
    app.use(notFound);
    app.use(errorHandler);
    return app;
};
